package com.crm.identity;
import com.crm.identity.entity.*;import com.crm.identity.enums.RoleType;import com.crm.identity.repository.*;import com.crm.identity.dto.*;import com.crm.identity.service.*;import com.crm.identity.security.JwtService;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.EnumSource;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
/** Isolated H2/MockMvc with actual security/services; no MySQL, Flyway or CRM server. */
@SpringBootTest(properties={"spring.config.name=application-test","spring.profiles.active=test","spring.datasource.url=jdbc:h2:mem:admin3h;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.flyway.enabled=false","eureka.client.enabled=false","app.bootstrap.admin.enabled=false"})
@AutoConfigureMockMvc(print=MockMvcPrint.NONE)
class AdministrationLifecycleIntegrationTest {
 @Autowired MockMvc mvc;@Autowired UserRepository users;@Autowired RoleRepository roles;@Autowired RefreshTokenRepository sessions;@Autowired JwtService jwt;@Autowired PasswordEncoder encoder;@Autowired ObjectMapper json;@Autowired DisplaySettingsRepository settings;
 User actor,target;String bearer;
 @BeforeEach void setup(){sessions.deleteAll();users.deleteAll();actor=user("super",RoleType.SUPER_ADMIN);target=user("worker",RoleType.EMPLOYEE);bearer=token(actor);}
 User user(String name,RoleType role){var u=new User();u.setUsername(name);u.setEmail(name+"@example.invalid");u.setFirstName("Synthetic");u.setLastName("Account");u.setPassword(encoder.encode("synthetic-password"));u.getRole().add(roles.findByRoleType(role).orElseThrow());return users.saveAndFlush(u);}
 String token(User u){var t=new RefreshToken();t.setUser(u);t.setToken(UUID.randomUUID().toString());t.setSessionId(UUID.randomUUID().toString());t.setExpiryDate(LocalDateTime.now().plusDays(1));sessions.saveAndFlush(t);return "Bearer "+jwt.generateSessionToken(u.getId(),u.getUsername(),u.getEmail(),true,u.getRole().stream().map(r->r.getRoleType().name()).toList(),t.getSessionId());}
 String body(Object value)throws Exception{return json.writeValueAsString(value);}
 JsonNode audit(String action)throws Exception{return json.readTree(mvc.perform(get("/api/users/administration/audit").header("Authorization",bearer).param("from",LocalDate.now(ZoneOffset.UTC).toString()).param("to",LocalDate.now(ZoneOffset.UTC).toString()).param("action",action)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andReturn().getResponse().getContentAsString());}
 @Test void directoryCombinesBoundFiltersAndReturnsTextIdsWithoutCredentials()throws Exception{mvc.perform(get("/api/users/directory").header("Authorization",bearer).param("keyword","worker").param("role","EMPLOYEE").param("state","active").param("size","1")).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1)).andExpect(jsonPath("$.content[0].id").value(target.getId().toString())).andExpect(jsonPath("$.content[0].password").doesNotExist());mvc.perform(get("/api/users/directory").header("Authorization",bearer).param("keyword","%")).andExpect(jsonPath("$.totalElements").value(0));}
 @ParameterizedTest @EnumSource(RoleType.class) void rolesCannotCrossAdministrationBoundary(RoleType role)throws Exception{String auth=token(user("role-check",role));mvc.perform(get("/api/users/administration/settings").header("Authorization",auth)).andExpect(status().is(role==RoleType.SUPER_ADMIN?200:403));mvc.perform(get("/api/users/display-settings").header("Authorization",auth)).andExpect(status().isOk());mvc.perform(get("/api/users/directory").header("Authorization",auth)).andExpect(status().is(role==RoleType.SUPER_ADMIN||role==RoleType.ADMIN?200:403));}
 @Test void creationIsAuditedAndTemporaryPasswordNeverGrantsAnAccessToken()throws Exception{mvc.perform(post("/api/users").header("Authorization",bearer).contentType("application/json").content(body(Map.of("firstName","New","lastName","Account","username","created","email","created@example.invalid","password","temporary-password")))).andExpect(status().isCreated());var created=users.findByUsername("created").orElseThrow();assertTrue(created.isPasswordChangeRequired());mvc.perform(post("/api/auth/login").contentType("application/json").content(body(Map.of("username","created","password","temporary-password")))).andExpect(status().isOk()).andExpect(jsonPath("$.passwordChangeRequired").value(true)).andExpect(jsonPath("$.token").isEmpty()).andExpect(jsonPath("$.refreshToken").isEmpty());var event=audit("USER_CREATED").path("content");assertEquals(created.getId().toString(),event.get(0).path("targetId").asText());assertFalse(event.toString().contains("temporary-password"));}
 @Test void passwordChangeRevokesAccessAndRefreshAndAllowsFreshLogin()throws Exception{String old=token(target);var current=sessions.findAll().stream().filter(t->t.getUser().getId().equals(target.getId())).findFirst().orElseThrow().getToken();mvc.perform(post("/api/auth/password").contentType("application/json").content(body(Map.of("login","worker","currentPassword","synthetic-password","newPassword","new-synthetic-password")))).andExpect(status().isNoContent());mvc.perform(get("/api/users/display-settings").header("Authorization",old)).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/refresh").contentType("application/json").content(body(Map.of("refreshToken",current)))).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/login").contentType("application/json").content(body(Map.of("username","worker","password","new-synthetic-password")))).andExpect(status().isOk()).andExpect(jsonPath("$.token").isNotEmpty());assertEquals(target.getId().toString(),audit("PASSWORD_CHANGED").path("content").get(0).path("actorId").asText());}
 @Test void requiredPasswordCanBeChangedBeforeAnySessionExists()throws Exception{target.setPasswordChangeRequired(true);users.saveAndFlush(target);mvc.perform(post("/api/auth/password").contentType("application/json").content(body(Map.of("login","worker","currentPassword","synthetic-password","newPassword","new-synthetic-password")))).andExpect(status().isNoContent());assertFalse(users.findById(target.getId()).orElseThrow().isPasswordChangeRequired());}
 @Test void invalidOrDisabledAccountCannotChangePassword()throws Exception{String original=target.getPassword();for(String current:List.of("wrong-password","synthetic-password")){if(current.equals("synthetic-password")){target.setEnabled(false);users.saveAndFlush(target);}mvc.perform(post("/api/auth/password").contentType("application/json").content(body(Map.of("login","worker","currentPassword",current,"newPassword","new-synthetic-password")))).andExpect(status().isUnauthorized());}assertEquals(original,users.findById(target.getId()).orElseThrow().getPassword());}
 @Test void explicitSettingsSaveIsVersionedAuditedAndNotASecretStore()throws Exception{var row=settings.findById(1L).orElseThrow();long old=row.getVersion();var payload=Map.of("companyName","Synthetic company","supportEmail","support@example.invalid","welcomeMessage","Welcome","version",old);mvc.perform(put("/api/users/administration/settings").header("Authorization",bearer).contentType("application/json").content(body(payload))).andExpect(status().isOk()).andExpect(jsonPath("$.companyName").value("Synthetic company"));mvc.perform(put("/api/users/administration/settings").header("Authorization",bearer).contentType("application/json").content(body(payload))).andExpect(status().isConflict());assertEquals("DISPLAY_SETTINGS_CHANGED",audit("DISPLAY_SETTINGS_CHANGED").path("content").get(0).path("action").asText());}
 @Test void administrativeRevocationInvalidatesTargetSession()throws Exception{String old=token(target);mvc.perform(post("/api/users/administration/users/"+target.getId()+"/revoke-sessions").header("Authorization",bearer)).andExpect(status().isOk());mvc.perform(get("/api/users/display-settings").header("Authorization",old)).andExpect(status().isUnauthorized());assertEquals(target.getId().toString(),audit("SESSIONS_REVOKED").path("content").get(0).path("targetId").asText());}
 @Test void noMutationOrRemovalOfAuditIsExposedAndDatesAreBounded()throws Exception{mvc.perform(delete("/api/users/administration/audit/1").header("Authorization",bearer)).andExpect(status().isMethodNotAllowed());mvc.perform(get("/api/users/administration/audit").header("Authorization",bearer).param("from","2020-01-01").param("to","2026-12-31")).andExpect(status().isBadRequest());mvc.perform(get("/api/users/administration/audit")).andExpect(status().isUnauthorized());}
 @Test void roleAndStatusWritesAreAuditedWithoutProfileOrCredentialMetadata()throws Exception{mvc.perform(put("/api/users/"+target.getId()+"/roles").header("Authorization",bearer).contentType("application/json").content("{\"roles\":[\"CLIENT\"]}")).andExpect(status().isOk());mvc.perform(patch("/api/users/"+target.getId()+"/status").header("Authorization",bearer).contentType("application/json").content("{\"enabled\":false}")).andExpect(status().isOk());for(String action:List.of("ROLES_CHANGED","STATUS_CHANGED")){var events=audit(action).path("content");assertEquals(target.getId().toString(),events.get(0).path("targetId").asText());assertFalse(events.toString().contains("example.invalid"));assertFalse(events.toString().contains("synthetic-password"));}}
 @Test void invalidHttpDatesRolesAndBodiesAre400WithoutReceivedValues()throws Exception{mvc.perform(get("/api/users/administration/audit").header("Authorization",bearer).param("from","private-invalid-date").param("to","2026-11-08")).andExpect(status().isBadRequest()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-invalid-date"))));mvc.perform(get("/api/users/directory").header("Authorization",bearer).param("role","private-role")).andExpect(status().isBadRequest()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-role"))));mvc.perform(post("/api/auth/password").contentType("application/json").content("not-json")).andExpect(status().isBadRequest());}
 @Test void forcedInitialChangeAlsoRejectsArtificiallySignedExistingSessions()throws Exception{String prior=token(target);target.setPasswordChangeRequired(true);users.saveAndFlush(target);mvc.perform(get("/api/users/display-settings").header("Authorization",prior)).andExpect(status().isUnauthorized());}
}
